import{c as a,Q as l,j as s,m as o}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"通信网络构建案例分析","description":"","frontmatter":{"title":"通信网络构建案例分析"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/通信网络构建案例分析.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/通信网络构建案例分析.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/通信网络构建案例分析.md"};function r(e,t,n,c,d,u){return l(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="通信网络构建案例分析" tabindex="-1">通信网络构建案例分析 <a class="header-anchor" href="#通信网络构建案例分析" aria-label="Permalink to &quot;通信网络构建案例分析&quot;">​</a></h1><blockquote><p>共 2 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-在ipv6园区网建设中-当部分用户无法部署双栈网络时-为了将纯ipv6用户接入ipv6网络-最适合采用的技术方案是-。" tabindex="-1">Q1. 在IPv6园区网建设中，当部分用户无法部署双栈网络时，为了将纯IPv6用户接入IPv6网络，最适合采用的技术方案是（）。 <a class="header-anchor" href="#q1-在ipv6园区网建设中-当部分用户无法部署双栈网络时-为了将纯ipv6用户接入ipv6网络-最适合采用的技术方案是-。" aria-label="Permalink to &quot;Q1. 在IPv6园区网建设中，当部分用户无法部署双栈网络时，为了将纯IPv6用户接入IPv6网络，最适合采用的技术方案是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 在核心层部署NAT64网关进行协议转换</li><li><strong>B.</strong> 采用ISATAP自动隧道技术建立用户端到出口路由器的连接</li><li><strong>C.</strong> 在汇聚层配置IPv6静态路由表进行流量转发</li><li><strong>D.</strong> 使用VRRP协议实现IPv6网关的冗余保护</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-在网络系统架构设计中-关于网络可靠性与网络可用性的区别-下列说法正确的是-。" tabindex="-1">Q2. 在网络系统架构设计中，关于网络可靠性与网络可用性的区别，下列说法正确的是（）。 <a class="header-anchor" href="#q2-在网络系统架构设计中-关于网络可靠性与网络可用性的区别-下列说法正确的是-。" aria-label="Permalink to &quot;Q2. 在网络系统架构设计中，关于网络可靠性与网络可用性的区别，下列说法正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 网络可靠性通过单独提升各功能部件的稳定性来保证连续性服务，而网络可用性需要各部件相互协同、冗余备份等复杂网络连接来提供</li><li><strong>B.</strong> 网络可用性通过单独提升各功能部件的稳定性来保证连续性服务，而网络可靠性需要各部件相互协同、冗余备份等复杂网络连接来提供</li><li><strong>C.</strong> 网络可靠性和网络可用性都是通过单独提升各功能部件的稳定性来实现的</li><li><strong>D.</strong> 网络可靠性和网络可用性都需要通过各部件相互协同、冗余备份等复杂网络连接来提供</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details>',8)])])}const g=a(i,[["render",r]]);export{p as __pageData,g as default};
